with gaps as (select *, case when event_time - lag(event_time) over (partition by page order by event_time, id) > interval '30' day then 1 else 0 end as is_new_burst from web_events), islands as (select *, sum(is_new_burst) over (partition by page order by event_time, id rows between unbounded preceding and current row) as session_id_2 from gaps) select s.id, s.session_id, s.event_type, s.event_time, s.duration_sec, s.is_new_burst, s.session_id_2, case when event_type rlike '^(purchase|click)$' then 'GROUP_A' when event_type rlike '^(page_view|add_to_cart)$' then 'PRIORITY' else 'GROUP_B' end as event_type_zone, (select sum(x.duration_sec) from web_events x where x.session_id = s.session_id) as sum_web_event_duration_sec from islands s order by is_new_burst;
